Here is the commit message:
smb/client: fix out-of-bounds read in smb2_compound_op()

If a server sends a truncated response but a large OutputBufferLength, and
terminates the EA list early, check_wsl_eas() returns success without
validating that the entire OutputBufferLength fits within iov_len.

Then smb2_compound_op() does:
    memcpy(idata->wsl.eas, data[0], size[0]);

Where size[0] is OutputBufferLength. If iov_len is smaller than size[0],
memcpy can read beyond the end of the rsp_iov allocation and leak adjacent
kernel heap memory.

Link: https://lore.kernel.org/linux-cifs/d998240c-aca9-420d-9dbd-f5ba24af19e0@chenxiaosong.com/
Fixes: ea41367b2a60 ("smb: client: introduce SMB2_OP_QUERY_WSL_EA")
Cc: stable@vger.kernel.org
Signed-off-by: Zisen Ye <zisenye@stu.xidian.edu.cn>
Reviewed-by: ChenXiaoSong <chenxiaosong@kylinos.cn>
Signed-off-by: Steve French <stfrench@microsoft.com>

Here is the root cause:
The check_wsl_eas() function fails to validate that the entire EA data region declared by OutputBufferLength fits within the received iov buffer. It only checks each EA entry against the iov's end, but if the server terminates the EA list early and provides a larger OutputBufferLength than the actual data, the function returns success, allowing smb2_compound_op() to memcpy beyond the iov allocation using that oversized length, causing an out-of-bounds read.

Here is the patch:

 static int check_wsl_eas(struct kvec *rsp_iov)
 {
 	struct smb2_file_full_ea_info *ea;
 	struct smb2_query_info_rsp *rsp = rsp_iov->iov_base;
 	unsigned long addr;
 	u32 outlen, next;
 	u16 vlen;
 	u8 nlen;
-	u8 *end;
+	u8 *ea_end, *iov_end;

 	outlen = le32_to_cpu(rsp->OutputBufferLength);
 	if (outlen < SMB2_WSL_MIN_QUERY_EA_RESP_SIZE ||
 	    outlen > SMB2_WSL_MAX_QUERY_EA_RESP_SIZE)
 		return -EINVAL;

 	ea = (void *)((u8 *)rsp_iov->iov_base +
 		      le16_to_cpu(rsp->OutputBufferOffset));
-	end = (u8 *)rsp_iov->iov_base + rsp_iov->iov_len;
+	ea_end = (u8 *)ea + outlen;
+	iov_end = (u8 *)rsp_iov->iov_base + rsp_iov->iov_len;
+	if (ea_end > iov_end)
+		return -EINVAL;
+
 	for (;;) {
-		if ((u8 *)ea > end - sizeof(*ea))
+		if ((u8 *)ea > ea_end - sizeof(*ea))
 			return -EINVAL;

 		nlen = ea->ea_name_length;
 		vlen = le16_to_cpu(ea->ea_value_length);
 		if (nlen != SMB2_WSL_XATTR_NAME_LEN ||
-		    (u8 *)ea->ea_data + nlen + 1 + vlen > end)
+		    (u8 *)ea->ea_data + nlen + 1 + vlen > ea_end)
 			return -EINVAL;

 		switch (vlen) {
 		case 4:
 			if (strncmp(ea->ea_data, SMB2_WSL_XATTR_UID, nlen) &&
 			    strncmp(ea->ea_data, SMB2_WSL_XATTR_GID, nlen) &&
 			    strncmp(ea->ea_data, SMB2_WSL_XATTR_MODE, nlen))
 				return -EINVAL;
 			break;
 		case 8:
 			if (strncmp(ea->ea_data, SMB2_WSL_XATTR_DEV, nlen))
 				return -EINVAL;
 			break;
 		case 0:
 			if (!strncmp(ea->ea_data, SMB2_WSL_XATTR_UID, nlen) ||
 			    !strncmp(ea->ea_data, SMB2_WSL_XATTR_GID, nlen) ||
 			    !strncmp(ea->ea_data, SMB2_WSL_XATTR_MODE, nlen) ||
 			    !strncmp(ea->ea_data, SMB2_WSL_XATTR_DEV, nlen))
 				break;
 			fallthrough;
 		default:
 			return -EINVAL;
 		}

 		next = le32_to_cpu(ea->next_entry_offset);
 		if (!next)
 			break;
 		if (!IS_ALIGNED(next, 4) ||
 		    check_add_overflow((unsigned long)ea, next, &addr))
 			return -EINVAL;
 		ea = (void *)addr;
 	}
 	return 0;
 }



